#include <iostream>
#include <string>
using namespace std;

int main() {
    int k;
    string s;
    cin >> k >> s;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') {
            s[i] = (s[i] - 'A' + k) % 26 + 'A';
        } else if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (s[i] - 'a' + k) % 26 + 'a';
        }
    }
    cout << s << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    int a[100000];
    for (int i = 0; i < n; i++) cin >> a[i];
    k = k % n;
    if (k == 0) {
        for (int i = 0; i < n; i++) cout << a[i] << (i<n-1?" ":"\n");
        return 0;
    }
    // 三次反转法
    // reverse all
    for (int i = 0; i < n/2; i++) swap(a[i], a[n-1-i]);
    // reverse first k
    for (int i = 0; i < k/2; i++) swap(a[i], a[k-1-i]);
    // reverse rest
    for (int i = k; i < (n+k)/2; i++) swap(a[i], a[n-1-i+k]);
    for (int i = 0; i < n; i++) cout << a[i] << (i<n-1?" ":"\n");
    return 0;
}
